import { useEffect, useRef, useState, type CSSProperties, type MouseEvent } from 'react';
import { Signature, Sparkles } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import TeamLogo from '@/components/brand/TeamLogo';
import { findNFLTeam } from '@/utils/nflTeams';
import { POSITION_NAMES } from '@/utils/playerMeta';
import { prizmInfo, prizmSerial, prizmStamp, tierLabel, variantLabel, type PackCard } from '@/utils/collection';
import CollectibleCard, { PlayerJersey } from './CollectibleCard';
import CardBackArt from './CardBackArt';
import type { CardInfo } from './useCardPool';
import { AUTO_WRITE_DELAY_MS, AUTO_WRITE_MS, isPrizmChase, type WkBeat, type WkStage } from './walkoutBeats';
import { homeUniform, kitStamp, kitUniform } from './art/sprite/uniforms';
import { KitFigureImg, useKitFigure } from './tunnel/KitSprite';
import './kits.css';
import AutographCanvas from './autograph/AutographCanvas';
import { useAutographFor } from './autograph/sample';
import { autographValue, fmtMult, inkRowOf, parallelOf, serialStr } from '@/config/autographs';
import { displayName } from '@/utils/displayName';
import { CAREER_LABEL } from '@/config/ovr';

/** Firework bursts: [left %, top %, delay s]; Legendary fires a second volley. */
const VOLLEY = [
  [22, 32, 0],
  [78, 26, 0.22],
  [50, 16, 0.45],
] as const;
const VOLLEY_2 = [
  [34, 22, 0.8],
  [66, 36, 1.0],
] as const;
const SPARKS_PER_BURST = 14;

/** Shatter: 12 glass triangles from the card's centre to its edge, each flying outward. */
const EDGE = [
  [0, 0],
  [33, 0],
  [66, 0],
  [100, 0],
  [100, 33],
  [100, 66],
  [100, 100],
  [66, 100],
  [33, 100],
  [0, 100],
  [0, 66],
  [0, 33],
] as const;
const SHARDS = EDGE.map(([x1, y1], i) => {
  const [x2, y2] = EDGE[(i + 1) % EDGE.length];
  const cx = (50 + x1 + x2) / 3 - 50;
  const cy = (52 + y1 + y2) / 3 - 52;
  const len = Math.hypot(cx, cy) || 1;
  return {
    clip: `polygon(50% 52%, ${x1}% ${y1}%, ${x2}% ${y2}%)`,
    dx: `${((cx / len) * 120).toFixed(0)}%`,
    dy: `${((cy / len) * 120).toFixed(0)}%`,
    rot: `${((i * 47) % 120) - 60}deg`,
  };
});
const PRISM_BITS = 30;

const CLUES: WkStage[] = ['logo', 'pos', 'ovr'];

const reducedMotion = () => {
  try {
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  } catch {
    return false;
  }
};

/** OVR counting up to its value; writes the number straight to the DOM on animation frames (no re-renders). */
const OvrCount = ({ to, ms }: { to: number | null; ms: number }) => {
  const ref = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (to == null) {
      el.textContent = '–';
      return;
    }
    if (reducedMotion()) {
      el.textContent = String(to);
      return;
    }
    const from = Math.max(40, to - 38);
    const t0 = performance.now();
    let raf = 0;
    const tick = (t: number) => {
      const k = Math.min(1, Math.max(0, (t - t0) / ms));
      const e = 1 - (1 - k) ** 4;
      el.textContent = String(Math.round(from + (to - from) * e));
      if (k < 1) raf = requestAnimationFrame(tick);
    };
    el.textContent = String(from);
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [to, ms]);
  return <span ref={ref} aria-hidden="true" />;
};

interface WalkoutProps {
  card: PackCard;
  info: CardInfo;
  total: number;
  beats: WkBeat[];
  step: number;
  reduced: boolean;
  badge?: string;
  /** Tap anywhere: next stage now */
  onAdvance: () => void;
  onSkip: () => void;
  onDone: () => void;
  /** Reveal every remaining card (shown while other cards are still face down) */
  onRevealAll?: () => void;
  /**
   * Played inside the pack opening's tunnel (tunnel/PackTunnel.tsx): no tunnel of its own (the scene shows through),
   * and the player runs out of it: his game sprite in the pulled kit, a silhouette against the light until the card
   * flips, then lit and celebrating on the turf at the mouth.
   */
  tunnel?: boolean;
}

/** When each turn passes edge-on (ms from its start): the faces swap then, so iOS never draws both (collection.css). */
const FLIP_EDGE_MS = 114;
const FLIP_TURN_MS = 950;
/** The holo twist's 360: starts 650 ms in; the back faces the camera between these times (normal, Legendary). */
const SPIN = { normal: { start: 650, back: 1400, front: 1905, end: 3150 }, legendary: { start: 650, back: 1550, front: 2157, end: 3650 } };

/**
 * FUT-style walkout for Epic+ pulls and every holo: a dark tunnel with light beams, fireworks in the TIER colour,
 * a team-colour sweep and logo, the position, the OVR counting up, a silhouette walking out, then the card flips.
 * A holo looks like a normal walkout of its tier until after the flip; then the twist: white flash, prismatic
 * shockwave, the card shatters and reforms as holo, prism confetti, a HOLO stamp, a screen shake and a slow 360°.
 * A card that carries an autograph ends on its own beat: AUTOGRAPH, then the autograph card with his signature writing
 * itself left to right (drawn whole with reduced motion). A non-home kit shows its stamp under the card once it has
 * flipped (ALT KIT · <label>); an era kit holds it back for its own THROWBACK beat after the flip and any twist. A
 * Prizm colour parallel shows its stamp the same way (PRIZM RED /199); a Gold or Black holds it for its PRIZM beat.
 */
const Walkout = ({ card, info, total, beats, step, reduced, badge, onAdvance, onSkip, onDone, onRevealAll, tunnel = false }: WalkoutProps) => {
  const team = findNFLTeam(info.player.team);
  const stage = beats[Math.min(step, beats.length - 1)].stage;
  const reached = (s: WkStage) => {
    const k = beats.findIndex((b) => b.stage === s);
    return k >= 0 && step >= k;
  };
  const holo = card.finish === 'holo';
  const twisted = holo && reached('twist');
  const legendary = card.tier === 'legendary';
  const isFinal = stage === 'final';
  // The Autograph variant's autograph: the pull's own, else (an Art lab walkout) his sample roll
  const sampled = useAutographFor(info, card.finish, card.auto ?? 'sample');
  const auto = card.variant === 'auto' ? sampled : undefined;
  const signed = !!auto && reached('auto');
  const uniform = card.variant === 'auto' ? null : kitUniform(info.player, card.kit, card.variant, card.finish);
  const stamp = uniform ? kitStamp(uniform) : null;
  const throwback = !!uniform?.era;
  const kitShown = !!stamp && reached('flip') && (!throwback || reached('kit')) && (!holo || twisted || isFinal);
  const par = card.variant === 'number' ? card.prizm : undefined;
  const parChase = isPrizmChase(card);
  const parShown = !!par && reached('flip') && (!parChase || reached('prizm')) && (!holo || twisted || isFinal);
  const doneRef = useRef<HTMLButtonElement>(null);
  const rootRef = useRef<HTMLDivElement>(null);
  // The runner (tunnel only): his sprite in the pulled kit (an autograph has no kit roll: home)
  const runKit = tunnel ? uniform ?? homeUniform(info.player.team) : null;
  const figRun = useKitFigure(info.player, runKit, 'run');
  const figCel = useKitFigure(info.player, runKit, 'celebrate');
  const runner = tunnel && !reduced && figRun.status === 'ready';
  // The flip (and a holo's 360) without iOS flicker: the far face is hidden outright once the card is edge-on, and
  // blend-mode / moving finish layers are off while it turns (data-turning), as in the card detail (useFlipFaces.ts)
  const flipped = reached('flip');
  const [face, setFace] = useState<'back' | 'front'>('back');
  const [turning, setTurning] = useState(false);
  useEffect(() => {
    if (!flipped) return;
    if (reduced) {
      setFace('front');
      return;
    }
    setTurning(true);
    const a = window.setTimeout(() => setFace('front'), FLIP_EDGE_MS);
    const b = window.setTimeout(() => setTurning(false), FLIP_TURN_MS);
    return () => {
      window.clearTimeout(a);
      window.clearTimeout(b);
    };
  }, [flipped, reduced]);
  useEffect(() => {
    if (!twisted || reduced) return;
    const s = SPIN[legendary ? 'legendary' : 'normal'];
    const ids = [
      window.setTimeout(() => setTurning(true), s.start),
      window.setTimeout(() => setFace('back'), s.back),
      window.setTimeout(() => setFace('front'), s.front),
      window.setTimeout(() => setTurning(false), s.end),
    ];
    return () => ids.forEach((id) => window.clearTimeout(id));
  }, [twisted, reduced, legendary]);
  // Focus the stage (so Space / Enter reach Skip next), then Continue once it is over
  useEffect(() => {
    rootRef.current?.focus({ preventScroll: true });
  }, []);
  useEffect(() => {
    if (isFinal) doneRef.current?.focus();
  }, [isFinal]);

  const photo = info.player.isRealLegend ? info.player.photo?.url : undefined;
  const style = (team ? { '--wk-a': `hsl(${team.primaryColor})`, '--wk-b': `hsl(${team.secondaryColor})` } : {}) as CSSProperties;
  const teamName = team?.name ?? (info.player.isRealLegend ? 'NFL Legend' : info.cardTeam);
  const ovrBeat = beats.find((b) => b.stage === 'ovr')?.ms ?? 1000;

  const hero = CLUES.includes(stage) ? stage : null;
  const hud = CLUES.filter((c) => reached(c) && c !== hero);
  const showClues = !reached('flip');

  const tap = (e: MouseEvent) => {
    if ((e.target as HTMLElement).closest('button')) return;
    onAdvance();
  };

  return (
    // Tapping the stage advances one beat; Skip / Continue are the keyboard path
    <div
      className={cn(
        'wk',
        `wk--t-${card.tier}`,
        `wk--${stage}`,
        reduced && 'wk--rm',
        tunnel && 'wk--tunnel',
        reached('flares') && 'wk--lit',
        reached('sweep') && 'wk--team',
        reached('walk') && 'wk--out',
        reached('flip') && 'wk--carded',
        twisted && 'wk--holo',
        signed && 'wk--signed',
      )}
      style={style}
      onClick={tap}
      ref={rootRef}
      tabIndex={-1}
      role="region"
      aria-label={`${tierLabel(card.tier)} walkout`}
    >
      <div className="wk__shake">
        {!reduced && (
          <>
            {!tunnel && (
              <>
                <span className="wk__tunnel" aria-hidden="true" />
                <span className="wk__floor" aria-hidden="true" />
                <span className="wk__exit" aria-hidden="true" />
                <span className="wk__beam wk__beam--l" aria-hidden="true" />
                <span className="wk__beam wk__beam--r" aria-hidden="true" />
                {legendary && (
                  <>
                    <span className="wk__beam wk__beam--cl" aria-hidden="true" />
                    <span className="wk__beam wk__beam--cr" aria-hidden="true" />
                  </>
                )}
              </>
            )}
            <span className="wk__wash" aria-hidden="true" />
          </>
        )}
        {!reduced && reached('flares') && (
          <span className="wk__fireworks" aria-hidden="true">
            {[...VOLLEY, ...(legendary ? VOLLEY_2 : [])].map(([x, y, d], b) => (
              <span key={b} className="wk__fw" style={{ left: `${x}%`, top: `${y}%`, '--d': `${d}s` } as CSSProperties}>
                {Array.from({ length: SPARKS_PER_BURST }, (_, i) => (
                  <i key={i} style={{ '--i': i } as CSSProperties} />
                ))}
              </span>
            ))}
          </span>
        )}
        {!reduced && stage === 'sweep' && <span className="wk__sweep" aria-hidden="true" />}

        {showClues && (
          <>
            <div className="wk__hud" aria-hidden="true">
              {hud.map((c) => (
                <span key={c} className={cn('wk__chip', `wk__chip--${c}`)}>
                  {c === 'logo' && (team ? <TeamLogo team={info.player.team} size={30} decorative /> : <span className="wk__star">★</span>)}
                  {c === 'pos' && info.player.position}
                  {c === 'ovr' && (info.ovr ?? '–')}
                </span>
              ))}
            </div>
            <div className="wk__hero" aria-live="polite">
              {hero === 'logo' && (
                <span key="logo" className="wk__logo">
                  <span className="wk__logo-mark">
                    {team ? <TeamLogo team={info.player.team} size={112} decorative /> : <span className="wk__star wk__star--big">★</span>}
                  </span>
                  <span className="wk__team-name">{teamName}</span>
                </span>
              )}
              {hero === 'pos' && (
                <span key="pos" className="wk__pos">
                  <span className="wk__pos-code">{info.player.position}</span>
                  <span className="wk__pos-name">{POSITION_NAMES[info.player.position] ?? info.player.position}</span>
                </span>
              )}
              {hero === 'ovr' && (
                <span key="ovr" className="wk__ovr" aria-label={`${CAREER_LABEL} ${info.ovr ?? 'unknown'}`}>
                  <OvrCount to={info.ovr} ms={Math.min(1100, ovrBeat * 0.75)} />
                  <span className="wk__ovr-label">{CAREER_LABEL}</span>
                </span>
              )}
            </div>
          </>
        )}

        {runner && reached('walk') && !signed && (
          <span className={cn('wk-run', flipped && 'wk-run--in')} aria-hidden="true">
            <span className="wk-run__path">
              <span className="wk-run__hop">
                <KitFigureImg fig={figRun} className="wk-run__pose wk-run__pose--run" />
                <KitFigureImg fig={figCel.status === 'ready' ? figCel : figRun} className="wk-run__pose wk-run__pose--cel" />
              </span>
            </span>
          </span>
        )}
        {!reduced && !runner && reached('walk') && !reached('flip') && (
          <span className={cn('wk__sil', photo && 'wk__sil--photo')} aria-hidden="true">
            {photo ? <img src={photo} alt="" referrerPolicy="no-referrer" draggable={false} /> : <PlayerJersey number={info.number} id={`wk-${info.key.replace(/\W/g, '')}`} />}
          </span>
        )}

        {signed && auto && (
          <div className="wk__auto">
            <span className="wk__auto-kicker" aria-hidden="true">
              <Signature className="h-6 w-6" /> Autograph
            </span>
            <div className="wk__auto-card">
              <AutographCanvas snap={auto.snap} roll={auto.roll} cacheKey={reduced ? auto.id : undefined} write={!reduced} writeDelayMs={AUTO_WRITE_DELAY_MS} writeMs={AUTO_WRITE_MS} />
            </div>
            <p className="wk__auto-meta">
              {parallelOf(auto.roll.parallel).label} · {serialStr(auto.roll)} · {inkRowOf(auto.roll).label}
              {auto.roll.inscription ? ` · inscribed ${auto.roll.inscription}` : ''} · <b>{fmtMult(autographValue(auto.roll).total)}</b> the card
            </p>
          </div>
        )}

        {reached('flip') && !signed && (
          <div className="wk__card">
            {twisted && !reduced && (
              <>
                <span className="wk__rays" aria-hidden="true" />
                <span className="wk__wave" aria-hidden="true" />
                <span className="wk__wave wk__wave--2" aria-hidden="true" />
                {legendary && <span className="wk__wave wk__wave--3" aria-hidden="true" />}
              </>
            )}
            <div className="wk__spin">
              <div className="wk__flip" data-face={face} data-turning={turning ? '' : undefined}>
                <div className="wk__face">
                  <CollectibleCard
                    owned
                    live
                    large
                    player={info.player}
                    tier={card.tier}
                    finish={holo && !twisted ? 'base' : card.finish}
                    variant={card.variant}
                    kit={card.kit}
                    prizm={par}
                    autograph={auto}
                    ovr={info.ovr}
                    number={info.number}
                    stats={info.stats}
                    setNo={info.setNo}
                    setTotal={total}
                    badge={isFinal ? badge : undefined}
                  />
                  {twisted && <span className="wk__prism-sweep" aria-hidden="true" />}
                </div>
                <div className="wk__face wk__face--back" aria-hidden="true">
                  <CardBackArt />
                </div>
              </div>
            </div>
            {twisted && !reduced && (
              <span className="wk__shards" aria-hidden="true">
                {SHARDS.map((s, i) => (
                  <i key={i} style={{ clipPath: s.clip, '--dx': s.dx, '--dy': s.dy, '--rot': s.rot } as CSSProperties} />
                ))}
              </span>
            )}
            {twisted && !reduced && (
              <span className="wk__prism" aria-hidden="true">
                {Array.from({ length: legendary ? PRISM_BITS + 14 : PRISM_BITS }, (_, i) => (
                  <i key={i} style={{ '--i': i, '--n': legendary ? PRISM_BITS + 14 : PRISM_BITS } as CSSProperties} />
                ))}
              </span>
            )}
            {twisted && (
              <span className="wk__stamp" aria-hidden="true">
                <Sparkles className="h-5 w-5" /> Holo
              </span>
            )}
            {kitShown && (
              <span className={cn('wk__kit', throwback ? 'wk__kit--era' : 'wk__kit--alt')} aria-hidden="true">
                {stamp}
              </span>
            )}
            {par && parShown && (
              <span className={cn('wk__prizm', `wk__prizm--${par.c}`, kitShown && 'wk__prizm--stacked')} aria-hidden="true">
                {prizmStamp(par.c)}
                {prizmInfo(par.c).run > 1 && <small> {prizmSerial(par)}</small>}
              </span>
            )}
          </div>
        )}
        {!reduced && stage === 'kit' && <span className="wk__kit-glow" aria-hidden="true" />}
        {!reduced && stage === 'prizm' && par && <span className={cn('wk__prizm-glow', `wk__prizm-glow--${par.c}`)} aria-hidden="true" />}
        {twisted && !reduced && <span className="wk__white" aria-hidden="true" />}
        {!reduced && (stage === 'flip' || stage === 'kit' || stage === 'prizm' || stage === 'auto') && <span key={stage} className="wk__flash" aria-hidden="true" />}
      </div>

      <p className="sr-only" role="status">
        {reached('flip')
          ? `${tierLabel(card.tier)}! ${displayName(info.player.name)}, ${variantLabel(card.variant)}${twisted ? '. Twist: it is a Holo!' : ''}${kitShown && uniform ? (throwback ? `. Throwback kit: ${uniform.label}!` : `. Alternate kit: ${uniform.label}`) : ''}${parShown && par ? `. Prizm ${prizmInfo(par.c).label} parallel, ${prizmSerial(par)}${parChase ? '!' : ''}` : ''}${signed && auto ? `. And an autograph: ${parallelOf(auto.roll.parallel).label} ${serialStr(auto.roll)}!` : ''}`
          : `${tierLabel(card.tier)} walkout`}
      </p>

      <div className="wk__actions">
        {!isFinal && !reduced && <span className="wk__hint">Tap to speed up</span>}
        {!isFinal ? (
          <>
            {onRevealAll && (
              <Button variant="ghost" size="sm" onClick={onRevealAll}>
                Reveal all
              </Button>
            )}
            <Button variant="outline" size="sm" onClick={onSkip}>
              Skip
            </Button>
          </>
        ) : (
          <Button ref={doneRef} onClick={onDone}>
            Continue
          </Button>
        )}
      </div>
    </div>
  );
};

export default Walkout;
