/*
 * The open card and the open player card live in slots (utils/slot.ts), so opening or closing them re-renders only
 * CollectionOverlays (the dialogs), never the binder behind them (about 75 ms of a slow phone's tap went to that).
 */
interface OverlaysProps {
  detailSlot: Slot<CardDetailTarget | null>;
  playerSlot: Slot<Player | null>;
  owned: ReturnType<typeof useCollection>['cards'];
  state: ReturnType<typeof useCollection>['state'];
  shardsPerPack: number;
  total: number;
  browsing: boolean;
  onBrowseClose: () => void;
  browseList: CardInfo[];
}

/** The card detail, the swipe browser and the player card: everything that opens over the Collection. */
const CollectionOverlays = ({ detailSlot, playerSlot, owned, state, shardsPerPack, total, browsing, onBrowseClose, browseList }: OverlaysProps) => {
  const detail = useSlot(detailSlot);
  const player = useSlot(playerSlot);
  // browseFocus follows CardDetail when it steps to another card on top of the browser; a fresh browse starts unfocused
  const [browseFocus, setBrowseFocus] = useState<string | null>(null);
  const [wasBrowsing, setWasBrowsing] = useState(browsing);
  if (browsing !== wasBrowsing) {
    setWasBrowsing(browsing);
    if (browsing && browseFocus !== null) setBrowseFocus(null);
  }
  return (
    <>
      <CardDetail
        target={detail}
        entry={detail && !detail.preview ? owned[detail.info.key] : undefined}
        shards={state.shards}
        shardsPerPack={shardsPerPack}
        display={detail ? state.display?.[detail.info.key] : undefined}
        total={total}
        onClose={() => detailSlot.set(null)}
        onNavigate={(info) => {
          detailSlot.set((d) => (d ? { info, list: d.list } : d));
          if (browsing) setBrowseFocus(info.key);
        }}
        onPlayer={(info) => {
          detailSlot.set(null);
          playerSlot.set(info.player);
        }}
      />
      <CardBrowser
        open={browsing}
        list={browseList}
        owned={owned}
        display={state.display}
        total={total}
        covered={!!detail || !!player}
        focusKey={browseFocus}
        onClose={onBrowseClose}
        onDetails={(info, variant, finish, from) => detailSlot.set({ info, list: browseList, variant, finish, from })}
      />
      <PlayerDetailCard player={player} onClose={() => playerSlot.set(null)} />
    </>
  );
};

const CollectionTab = () => {
  const { cards, byKey, tierPool, loaded } = useCardPool();
  const { state, cards: owned, fresh } = useCollection();
  const { content } = useLeagueContent();
  // Autographs freeze the pulled player's career details as of the pull
  const { freeze } = useAutographFreezer(byKey);

  // The binder's view, search, filters and sort (collection/binder/Binder.tsx); "My cards" is remembered per device
  const [bf, setBf] = useState<BinderFilterState>(() => ({ ...BINDER_DEFAULTS, mine: readMinePref() }));
  const { tier, finish, pos, team, sort } = bf;
  const missing = !bf.mine;
  const detailSlot = useNewSlot<CardDetailTarget | null>(null);
  const playerSlot = useNewSlot<Player | null>(null);
  const setDetail = detailSlot.set;
  const [opening, setOpening] = useState<PackType | null>(null);
  const [designs, setDesigns] = useState(false);
  const [preview, setPreview] = useState(false);
  const [artLab, setArtLab] = useState(false);
  // Swipe browser over the binder's filter (its focus lives in CollectionOverlays)
  const [browsing, setBrowsing] = useState(false);
  const [sellingDupes, setSellingDupes] = useState(false);
  // Once opened, the lazy dialogs stay mounted so they close with their animation and reopen instantly
  const [designsSeen, setDesignsSeen] = useState(false);
  const [artLabSeen, setArtLabSeen] = useState(false);
  useEffect(() => void (designs && setDesignsSeen(true)), [designs]);
  useEffect(() => void (artLab && setArtLabSeen(true)), [artLab]);

  // #collection?gift=<id> redeems a one-time gift; #collection?view=designs opens the Card designs gallery, ?view=art the Art lab
  useEffect(() => {
    const check = () => {
      const hash = window.location.hash;
      if (!hash.startsWith('#collection')) return;
      const gift = hash.match(GIFT_HASH)?.[1];
      if (gift) {
        const r = redeemGift(gift);
        if (r === 'granted') toast.success(`New packs added: ${giftSummary(gift)}`, { description: 'Tap a pack below to open it.' });
        else if (r === 'already') toast('That gift was already redeemed on this browser.');
        cleanHash();
      }
      if (DESIGNS_HASH.test(hash)) setDesigns(true);
      if (MARKET_HASH.test(hash)) window.setTimeout(() => document.getElementById('col-market')?.scrollIntoView({ block: 'start', behavior: reducedMotion() ? 'auto' : 'smooth' }), 50);
      if (ART_HASH.test(hash)) setArtLab(true);
    };
    check();
    window.addEventListener('hashchange', check);
    return () => window.removeEventListener('hashchange', check);
  }, []);

  const closeDesigns = () => {
    setDesigns(false);
    if (DESIGNS_HASH.test(window.location.hash)) cleanHash();
  };
  const closeArtLab = () => {
    setArtLab(false);
    if (ART_HASH.test(window.location.hash)) cleanHash();
  };

  const ownedCount = useMemo(() => cards.filter((c) => !!owned[c.key]).length, [cards, owned]);
  const variantCount = useMemo(() => variantsOwned(owned, cards.map((c) => c.key)), [cards, owned]);
  const tierStats = useMemo(
    () =>
      TIERS.map((t) => {
        const list = cards.filter((c) => c.tier === t.key);
        return { ...t, total: list.length, have: list.filter((c) => !!owned[c.key]).length };
      }),
    [cards, owned],
  );

  const showcase = useMemo(
    () =>
      cards
        .filter((c) => owned[c.key])
        .sort(
          (a, b) =>
            tierRank(b.tier) - tierRank(a.tier) ||
            finishRank(owned[b.key].best) - finishRank(owned[a.key].best) ||
            Object.keys(owned[b.key].variants).length - Object.keys(owned[a.key].variants).length ||
            (b.ovr ?? 0) - (a.ovr ?? 0),
        )
        .slice(0, 10),
    [cards, owned],
  );

  const sets = useMemo(() => {
    const players = cards.map((c) => c.player);
    const eras = (content?.eras ?? [])
      .map((era) => {
        const members = [
          ...new Map(
            era.keyPlayers
              .map((n) => matchPlayerByName(n, players))
              .filter((p): p is CardInfo['player'] => !!p)
              .map((p) => [`${p.position}:${displayName(p.name)}`, p] as const),
          ).values(),
        ];
        return { id: era.id, title: era.name, members };
      })
      .filter((a) => a.members.length > 0);
    const extra = [
      { id: 'legacy-elite', title: 'Legacy elite', members: cards.filter((c) => c.tier === 'legendary').map((c) => c.player) },
      { id: 'hof-wing', title: 'Hall of Fame', members: cards.filter((c) => !c.player.isRealLegend && isHallOfFamer(c.player)).map((c) => c.player) },
    ].filter((a) => a.members.length > 0);
    // Set progress counts every player × variant
    return [...extra, ...eras].map((a) => ({ ...a, have: variantsOwned(owned, a.members.map((p) => `${p.position}:${displayName(p.name)}`)), total: a.members.length * VARIANTS.length }));
  }, [cards, content, owned]);

  const teamOptions = useMemo(() => [...new Set(cards.map((c) => c.franchise))].sort(), [cards]);
  useEffect(() => {
    if (team !== 'all' && cards.length && !teamOptions.includes(team)) setBf((f) => ({ ...f, team: 'all' }));
  }, [team, cards.length, teamOptions]);

  const filtered = useMemo(() => {
    const list = cards.filter(
      (c) =>
        (tier === 'all' || c.tier === tier) &&
        (finish === 'all' || (!!owned[c.key] && Object.values(owned[c.key].variants).some((v) => v?.best === finish))) &&
        (pos === 'all' || c.player.position === pos) &&
        (team === 'all' || c.franchise === team) &&
        (missing || !!owned[c.key]) &&
        matchesQuery(c, bf.q),
    );
    const fr = (c: CardInfo) => (owned[c.key] ? finishRank(owned[c.key].best) : -1);
    const surname = (c: CardInfo) => surnameOf(c.player.name);
    const POS_ORDER = ['QB', 'RB', 'WR', 'TE', 'OL', 'LB', 'DB', 'DL'];
    let out = list;
    if (sort === 'ovr') out = [...list].sort((a, b) => (b.ovr ?? 0) - (a.ovr ?? 0) || a.setNo - b.setNo);
    else if (sort === 'tier') out = [...list].sort(byTierDesc);
    else if (sort === 'finish') out = [...list].sort((a, b) => fr(b) - fr(a) || byTierDesc(a, b));
    else if (sort === 'recent') out = [...list].sort((a, b) => (owned[b.key]?.last ?? 0) - (owned[a.key]?.last ?? 0) || a.setNo - b.setNo);
    else if (sort === 'name') out = [...list].sort((a, b) => surname(a).localeCompare(surname(b)) || a.player.name.localeCompare(b.player.name));
    else if (sort === 'pos')
      out = [...list].sort((a, b) => POS_ORDER.indexOf(a.player.position) - POS_ORDER.indexOf(b.player.position) || (b.ovr ?? 0) - (a.ovr ?? 0) || a.setNo - b.setNo);
    else if (sort === 'club') out = [...list].sort((a, b) => a.cardTeam.localeCompare(b.cardTeam) || (b.ovr ?? 0) - (a.ovr ?? 0) || a.setNo - b.setNo);
    return bf.rev ? [...out].reverse() : out;
  }, [cards, tier, finish, pos, team, missing, sort, owned, bf.q, bf.rev]);
  // First appearance staggers in; later filter changes and "Show more" only fade (utils/motion useStagger)
  const gridMotion = useStagger(loaded && cards.length > 0);
  // The swipe browser shows every owned card of the filter (not just the loaded page of the grid)
  const browseList = useMemo(() => filtered.filter((c) => !!owned[c.key]), [filtered, owned]);

  const shelf = SHELF_ORDER.filter((t) => packCount(state, t) > 0);
  const previewCards = useMemo(() => samplePack(designRows(cards), cards), [cards]);
  const openCard = (c: CardInfo, list: CardInfo[], from?: DOMRect) => setDetail({ info: c, list, from });
  const describe = (pc: { player: Player }) => byKey.get(`${pc.player.position}:${displayName(pc.player.name)}`)!;
  // What a card shows by default: the display choice when still owned, else auto (with the best kit owned there)
  const shown_ = (c: CardInfo) => {
    const d = displayWithKit(owned[c.key], state.display?.[c.key], c.player);
    return { variant: d.variant, finish: d.finish, pinned: d.pinned, kit: d.kit, prizm: d.prizm };
  };
  // Shard estimate for "about N packs to go": a Standard pack against this binder
  const poolKeys = useMemo(
    () => ({ common: tierPool.common.map(cardKey), rare: tierPool.rare.map(cardKey), epic: tierPool.epic.map(cardKey), legendary: tierPool.legendary.map(cardKey) }),
    [tierPool],
  );
  const shardsPerPack = useMemo(() => expectedShardsPerPack('standard', owned, poolKeys), [owned, poolKeys]);

  // Per-edition accent on the hero and pack shelf (utils/edition.ts): changes after an update, same for everyone
  const accent = editionAccent(content?.edition);
  // Binder skin unlocked by a portfolio milestone (utils/economy.ts), when switched on
  const binderSkin = activeCosmetic(state, 'binder');

  // the league file is still on its way: the football holds the page's height instead of a 0 / 0 binder that fills in later
  if (!loaded) return <PixelLoader label="Collection" what="the collection" minHeight="70vh" className="container justify-start pt-[18vh]" />;

  return (
    <div className="rv-load-in container space-y-6 px-4 py-5 sm:px-6 sm:py-8">
      {/* Hero */}
      <section aria-labelledby="col-title" className="col-hero p-4 sm:p-6" style={{ ['--ed' as string]: accent.hsl }}>
        <div className="col-hero__row flex flex-wrap items-center gap-x-6 gap-y-4">
          <div
            className="col-ring"
            style={{ ['--p' as string]: pct(ownedCount, cards.length) }}
            role="img"
            aria-label={`${ownedCount} of ${cards.length} players collected`}
          >
            <span className="text-center leading-none">
              <span className="block font-display text-4xl font-extrabold tabular-nums">{ownedCount}</span>
              <span className="font-mono text-xs text-muted-foreground">/ {cards.length}</span>
            </span>
          </div>
          <div className="min-w-0 flex-1 space-y-3">
            <div className="col-hero__head flex flex-wrap items-center gap-2">
              <h1 id="col-title" className="font-display text-4xl uppercase italic sm:text-5xl">
                Collection
              </h1>
              <RulesPopover />
              {content?.edition?.label && (
                <span className="col-edition" title={`${displayName(accent.name)} edition: the shelf colour changes with every update`}>
                  {content.edition.label}
                </span>
              )}
            </div>
            <ul className="col-hero__tiers flex flex-wrap gap-2" aria-label="Collected by tier">
              {tierStats.map((t) => (
                <li key={t.key} className={cn('col-gem', `col-gem--${t.key}`)}>
                  <i aria-hidden="true" />
                  <span className="font-semibold">{t.label}</span>
                  <span className="font-mono tabular-nums text-muted-foreground">
                    {t.have}/{t.total}
                  </span>
                </li>
              ))}
            </ul>
            <div className="flex flex-wrap items-center gap-3 text-xs text-muted-foreground">
              <span>
                <span className="font-mono text-foreground">{variantCount}</span> / {cards.length * VARIANTS.length} variants
              </span>
              <span className="inline-flex items-center gap-1">
                <Hammer className="h-3.5 w-3.5 text-sky-300" aria-hidden="true" />
                <span className="font-mono text-foreground">{state.shards.toLocaleString()}</span> shards
              </span>
              <button
                type="button"
                onClick={() => document.getElementById('col-exchange')?.scrollIntoView({ block: 'start', behavior: reducedMotion() ? 'auto' : 'smooth' })}
                className="inline-flex items-center gap-1 hover:text-foreground"
                aria-label={`${state.coins.toLocaleString()} coins: open the Exchange`}
              >
                <Coins className="h-3.5 w-3.5 text-gold" aria-hidden="true" />
                <span className="font-mono text-foreground">{state.coins.toLocaleString()}</span> coins
              </button>
              {/* Whether the browser keeps the collection (Home Screen app / persistent storage), utils/homeScreen.ts */}
              <StorageTag />
              <BackupButton />
              {IS_NFL && (
                <>
                  <button
                    type="button"
                    onClick={() => {
                      grantDemoPacks(tierPool);
                      toast.success('Demo: 25 of every pack and 1,000,000 coins added');
                    }}
                    className="link-chip text-gold"
                  >
                    Demo: add packs
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      if (window.confirm('Reset the NFL binder? Every card, pack and coin in this demo is erased.')) resetCollection();
                    }}
                    className="link-chip text-destructive"
                  >
                    Reset NFL binder
                  </button>
                </>
              )}
              <button type="button" onClick={() => setDesigns(true)} className="link-chip text-gold">
                <LayoutGrid className="h-3.5 w-3.5" aria-hidden="true" /> Card designs
              </button>
            </div>
          </div>
        </div>

        <div className="mt-4 space-y-3">
          <DailyDraw state={state} disabled={!loaded} />
          {shelf.length ? (
            <ul className="col-shelf" aria-label="Unopened packs">
              {shelf.map((t) => {
                const n = packCount(state, t);
                return (
                  <li key={t}>
                    <button
                      type="button"
                      className="col-pack"
                      onClick={() => setOpening(t)}
                      disabled={!loaded || !cards.length}
                      aria-label={`Open a ${PACKS[t].label}, ${n} unopened`}
                    >
                      {n > 1 && <span className="col-pack__stack" aria-hidden="true" />}
                      <span className={cn('pk-pack', `pk-pack--${t}`)}>
                        <PackArt type={t} small />
                      </span>
                      {/* Keyed by the count, so it pops each time a pack is opened (or earned) */}
                      <span key={n} className="col-pack__count" aria-hidden="true">
                        {n}
                      </span>
                      <span className="text-xs font-semibold">{PACKS[t].label.replace(/ Pack$/, '')}</span>
                    </button>
                  </li>
                );
              })}
            </ul>
          ) : (
            <p className="text-sm text-muted-foreground">No packs yet</p>
          )}
          <OpenAll
            state={state}
            types={shelf}
            disabled={!loaded || !cards.length}
            tierPool={tierPool}
            freeze={freeze}
            byKey={byKey}
            onCard={(c) => openCard(c, [c])}
          />
        </div>
      </section>

      {/* Binder: right under the packs, so the cards are the first thing after the shelf */}
      <Binder
        loaded={loaded}
        cards={cards}
        filtered={filtered}
        owned={owned}
        display={state.display}
        fresh={fresh}
        filters={bf}
        setFilters={setBf}
        teamOptions={teamOptions}
        ownedCount={ownedCount}
        skin={binderSkin}
        onOpen={(c, from) => openCard(c, browseList, from)}
        onSwipe={() => setBrowsing(true)}
        swipeCount={browseList.length}
        onSellDupes={() => setSellingDupes(true)}
      />

      {loaded && cards.length > 0 && <ShardWorkshop cards={cards} owned={owned} shards={state.shards} perPack={shardsPerPack} onOpen={(c) => openCard(c, [c])} />}

      {/* Showcase */}
      {showcase.length > 0 && (
        <section aria-labelledby="col-best">
          <h2 id="col-best" className="section-title">
            Best pulls
          </h2>
          <ul className={cn('col-showcase', gridMotion)}>
            {showcase.map((c) => (
              <li key={c.key} {...peekProps(c.player)}>
                <CollectibleCard
                  owned
                  live={owned[c.key].best === 'holo' || c.tier === 'legendary'}
                  player={c.player}
                  tier={c.tier}
                  {...shown_(c)}
                  ovr={c.ovr}
                  number={c.number}
                  stats={c.stats}
                  setNo={c.setNo}
                  setTotal={cards.length}
                  marks={owned[c.key].marks}
                  onOpen={(from) => openCard(c, showcase, from)}
                />
              </li>
            ))}
          </ul>
        </section>
      )}

      {loaded && (
        <AutographsSection
          autos={state.autos}
          onOpen={(a, from) => {
            const info = byKey.get(a.key);
            if (info) setDetail({ info, variant: 'auto', finish: a.finish, auto: a, from });
          }}
        />
      )}

      {/* Exchange (pack shop, bounties, sets, trade-up, milestones) above the Market (owner, 2026-11-17) */}
      {loaded && cards.length > 0 && (
        <Exchange
          cards={cards}
          byKey={byKey}
          tierPool={tierPool}
          state={state}
          content={content}
          freeze={freeze}
          onOpenPack={(t) => setOpening(t)}
          onOpenCard={(c) => openCard(c, [c])}
        />
      )}

      {/* Market */}
      {loaded && cards.length > 0 && (
        <section aria-labelledby="col-market" className="scroll-mt-20">
          <h2 id="col-market" className="section-title">
            Market
          </h2>
          <MarketGate>
            <MarketView byKey={byKey} owned={owned} autos={state.autos} onOpen={(info, list) => setDetail({ info, list })} />
          </MarketGate>
        </section>
      )}


      {/* Sets */}
      {sets.length > 0 && ownedCount > 0 && (
        <section aria-labelledby="col-sets">
          <h2 id="col-sets" className="sr-only">
            Sets
          </h2>
          <ul className="-mx-4 flex gap-2 overflow-x-auto px-4 pb-1 scrollbar-none sm:mx-0 sm:px-0">
            {sets.map((s) => {
              const done = s.have === s.total;
              return (
                <li
                  key={s.id}
                  className={cn('w-40 shrink-0 rounded-lg border px-2.5 py-2', done ? 'border-gold bg-gold/10' : 'border-line bg-panel/60')}
                  title={`${s.members.map((p) => p.name).join(', ')} (${s.have} of ${s.total} player variants)`}
                >
                  <p className="truncate text-xs font-semibold">{s.title}</p>
                  <p className="flex items-center gap-2">
                    <span className="block h-1 flex-1 overflow-hidden rounded-full bg-black/40" aria-hidden="true">
                      <span className="block h-full rounded-full bg-gold" style={{ width: `${pct(s.have, s.total)}%` }} />
                    </span>
                    <span className="font-mono text-[11px] tabular-nums text-muted-foreground">
                      {s.have}/{s.total}
                    </span>
                  </p>
                </li>
              );
            })}
          </ul>
        </section>
      )}

      <PackOpening
        type={opening}
        onClose={() => setOpening(null)}
        onTear={(t) => openPack(t, tierPool, freeze, KIT_SOURCE)}
        describe={describe}
        total={cards.length}
        remaining={opening ? packCount(state, opening) : 0}
        provenance={state.perfect[0]?.label}
      />
      <SellDuplicates open={sellingDupes} onClose={() => setSellingDupes(false)} byKey={byKey} state={state} />
      <PackOpening
        preview
        type={preview ? 'elite' : null}
        onClose={() => setPreview(false)}
        onTear={() => (previewCards.length ? previewCards : null)}
        describe={describe}
        total={cards.length}
        remaining={0}
      />
      <Suspense fallback={<DialogFallback />}>
        {(designs || designsSeen) && (
          <CardDesigns
            open={designs}
            onClose={closeDesigns}
            cards={cards}
            total={cards.length}
            onOpenCard={(info, t, f, v, from) => setDetail({ info, tier: t, finish: f, variant: v, preview: true, from })}
            onPreviewPack={() => setPreview(true)}
            onArtLab={() => setArtLab(true)}
          />
        )}
        {(artLab || artLabSeen) && <ArtLab open={artLab} onClose={closeArtLab} cards={cards} total={cards.length} />}
      </Suspense>
      <CollectionOverlays
        detailSlot={detailSlot}
        playerSlot={playerSlot}
        owned={owned}
        state={state}
        shardsPerPack={shardsPerPack}
        total={cards.length}
        browsing={browsing}
        onBrowseClose={() => setBrowsing(false)}
        browseList={browseList}
      />
    </div>
  );
};

export default CollectionTab;
